def calculate_coverage(N, required_differences):
    """Calculates the coverage of required_differences by a set S = {0, 1, ..., N-1}."""
    S = set(range(N))
    achieved_differences = set()

    # Calculate all positive differences x - y where x, y in S
    for x in S:
        for y in S:
            if x > y:
                diff = x - y
                achieved_differences.add(diff)

    # Calculate coverage
    coverage = len(required_differences.intersection(achieved_differences))
    return coverage, achieved_differences

